package ru.evolenta.server.service.impl;
import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
import org.slf4j.*;import org.springframework.stereotype.Service;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.ResponseEntity;
import ru.evolenta.server.dto.request.*;import ru.evolenta.server.dto.response.ExternalTaskFetchAndLockRespDTO;import ru.evolenta.server.service.*;
import ru.evolenta.pgs.worker.*;import ru.evolenta.pgs.worker.integration.RepositoryTaskAdapter;
/** Uses the transport present in example-service; no undocumented extendLock/failure calls. */
@Service @ConditionalOnProperty(name="worker.enabled",havingValue="true")
public class ExternalTaskExecutorServiceImpl implements ExternalTaskExecutorService {
 private static final Logger LOG=LoggerFactory.getLogger(ExternalTaskExecutorServiceImpl.class);
 private final CamundaIntegrationTaskService camunda;private final RepositoryTaskAdapter adapter;private final CheckpointStore store;private final Properties p;private final String worker;private final AtomicBoolean busy=new AtomicBoolean();
 public ExternalTaskExecutorServiceImpl(CamundaIntegrationTaskService camunda,RepositoryTaskAdapter adapter,CheckpointStore store,@org.springframework.beans.factory.annotation.Qualifier("rbuWorkerProperties") Properties rbuWorkerProperties){this.camunda=camunda;this.adapter=adapter;this.store=store;this.p=rbuWorkerProperties;this.worker=p.getProperty("worker.instanceId","rbu")+"-"+UUID.randomUUID();}
 @Scheduled(fixedDelayString="${worker.poll-millis:3000}") public void poll(){if(!busy.compareAndSet(false,true))return;try{ExternalTaskFetchAndLockReqDTO req=new ExternalTaskFetchAndLockReqDTO();req.setWorkerId(worker);req.setMaxTasks(1);ExternalTaskTopicReqDTO topic=new ExternalTaskTopicReqDTO();topic.setTopicName(p.getProperty("worker.topic","pgs-data-processing-v1"));topic.setLockDuration(Integer.parseInt(p.getProperty("worker.lockMillis","300000")));topic.setVariables(new String[]{"mainId","collectionName","camundaBusinessInfoId","rbuDomain","rbuProfile","rbuOperation","rbuContractVersion"});topic.setLocalVariables(false);topic.setDeserializeValues(false);req.setTopics(Collections.singletonList(topic));ResponseEntity<List<ExternalTaskFetchAndLockRespDTO>> response=camunda.fetchAndLockExternalTasks(req);if(response.getBody()!=null)for(ExternalTaskFetchAndLockRespDTO task:response.getBody())processExternalTask(task);}catch(Exception e){LOG.error("Advertising poll failed: {}",e.getClass().getSimpleName());}finally{busy.set(false);}}
 @Override public void processExternalTask(ExternalTaskFetchAndLockRespDTO task){String key=Util.hash(Util.obj("taskId",task.getId(),"policy","advertising-worker"));try{if(!worker.equals(task.getWorkerId()))throw new IllegalStateException("Task is not locked by this worker");Map<String,Object>failure=store.read(key);if(Util.bool(failure.get("manualReviewRequired"))){LOG.error("Task {} awaits operator review",task.getId());return;}if(task.getLockExpirationTime()==null)throw new IllegalStateException("No authoritative lock expiration returned");final long deadline=task.getLockExpirationTime().getTime();final long reserve=Long.parseLong(p.getProperty("worker.timeoutMillis","30000"))+1000;Operations.Lease lease=()->{if(Thread.currentThread().isInterrupted()||System.currentTimeMillis()>=deadline-reserve)throw new IllegalStateException("Task lock expires; stopping writes");};lease.check();CompleteExternalTaskReqDTO result=adapter.execute(task,lease);lease.check();result.setWorkerId(worker);camunda.completeExternalTask(task.getId(),result);store.save(key,Util.obj("status","COMPLETED","completedAt",Util.now()));LOG.info("Advertising task {} completed",task.getId());}catch(Exception e){try{Map<String,Object>prior=store.read(key);int attempts=Util.integer(prior.get("attempts"))+1;boolean manual=e instanceof IllegalArgumentException||attempts>=Integer.parseInt(p.getProperty("worker.maxLocalAttempts","3"));store.save(key,Util.obj("status","FAILED","attempts",attempts,"manualReviewRequired",manual,"taskId",task.getId(),"errorType",e.getClass().getSimpleName(),"failedAt",Util.now()));LOG.error("Task {} failed; attempts={}, manualReviewRequired={}, error={}",task.getId(),attempts,manual,e.getClass().getSimpleName());}catch(Exception journalError){LOG.error("Could not save failure for task {}: {}",task.getId(),journalError.getClass().getSimpleName());}}
 }
}
